// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Send 1 ether to the contract (this should be rejected by reference C, accepted by buggy M)
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        // If call succeeded, pastBlockTime would be updated; if reverted, it stays 0
        // In reference: msg.value != 10 ether => revert => success == false => pastBlockTime == 0
        // In bug: msg.value == 1 ether => no revert => success == true => pastBlockTime != 0
        // Assert that pastBlockTime == 0 => only reference passes; buggy version will have pastBlockTime > 0
        assertTrue(c.pastBlockTime() == 0);
    }
}

