pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 20 ether);

        // First call: succeeds in both contracts
        vm.prank(alice);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        uint pastAfterFirst = c.pastBlockTime();

        // Warp to same timestamp (no time advancement)
        // Second call: reference reverts due to require(block.timestamp > pastBlockTime); buggy contract succeeds.
        vm.prank(alice);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // The reference reverts so ok2 is false; buggy contract returns true.
        // The assertion that passes on reference (ok2 is false) will fail on buggy (ok2 is true).
        assertTrue(!ok2);
    }
}

