pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp to a known value
        vm.warp(1000);
        // Set initial pastBlockTime via a call with 10 ether (succeeds in both versions)
        vm.deal(address(0x1), 10 ether);
        vm.prank(address(0x1));
        c.fallback{value: 10 ether}();
        // Now call with 0 ether; reference reverts, buggy version accepts
        vm.deal(address(0x2), 0 ether);
        vm.prank(address(0x2));
        // Use try/catch to capture whether call reverts
        bool ok;
        try c.fallback{value: 0 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        // The buggy version sets pastBlockTime to 1000; reference leaves it unchanged (1000 as well because previous call set it)
        // Wait, both would have pastBlockTime = 1000 after the first call. But the buggy version on the second call would set it again to 1000 (same timestamp), but that would cause require(block.timestamp > pastBlockTime) to fail? No, pastBlockTime is 1000, block.timestamp is 1000, require fails. So buggy version would also revert. Let's re-think.
        // To make the bug observable, we need a scenario where buggy version succeeds and reference reverts. Use block.timestamp = 1 initially, pastBlockTime = 0. First call with 10 ether succeeds, sets pastBlockTime = 1. Then advance time to 2, send 0 ether: reference reverts on value, buggy passes value check but require(block.timestamp > pastBlockTime) passes because 2 > 1. So buggy updates pastBlockTime to 2.
        // Let's redo:
        c = new C(); // fresh instance
        vm.warp(1);
        vm.deal(address(0x1), 10 ether);
        vm.prank(address(0x1));
        c.fallback{value: 10 ether}(); // sets pastBlockTime = 1
        vm.warp(2);
        vm.deal(address(0x2), 0 ether);
        vm.prank(address(0x2));
        bool ok2;
        try c.fallback{value: 0 ether}() {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        // Reference: fail (ok2 = false). Buggy: succeed (ok2 = true).
        // But we need to assert reading c's public surface. Let's use address(c).balance? No, but we can assert on pastBlockTime: reference unchanged (1) vs buggy changed (2).
        // However if reference reverts, pastBlockTime remains 1; if buggy succeeds, it becomes 2.
        // We'll just assert that pastBlockTime == 2 means buggy (fails) and == 1 means reference (passes). We need one assertion the reference holds (pastBlockTime == 1) and buggy breaks (pastBlockTime == 2).
        assertTrue(c.pastBlockTime() == 1, "Reference holds: pastBlockTime unchanged");
    }
}

